function summarizeSelections(responses, allowedOptions) {
  if (!Array.isArray(allowedOptions) || allowedOptions.some(x => typeof x !== 'string' || x.length === 0) ||
      new Set(allowedOptions).size !== allowedOptions.length) {
    throw new TypeError('allowedOptions must contain unique non-empty strings');
  }
  if (!Array.isArray(responses)) throw new TypeError('responses must be an array');
  for (const response of responses) {
    if (!response || typeof response !== 'object' ||
        typeof response.respondent !== 'string' || response.respondent.length === 0 ||
        !Array.isArray(response.choices) || response.choices.some(x => typeof x !== 'string')) {
      throw new TypeError('invalid response');
    }
  }

  const allowed = new Set(allowedOptions);
  const entries = allowedOptions.map(option => ({ option, count: 0, respondents: [] }));
  const byOption = new Map(entries.map(entry => [entry.option, entry]));
  for (const response of responses) {
    const uniqueChoices = new Set(response.choices);
    for (const choice of uniqueChoices) {
      if (allowed.has(choice)) {
        const entry = byOption.get(choice);
        entry.count += 1;
        entry.respondents.push(response.respondent);
      }
    }
  }
  entries.sort((a, b) => b.count - a.count);
  return { totalResponses: responses.length, options: entries };
}

module.exports = { summarizeSelections };

