'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['summarizeSelections']);
const { summarizeSelections } = api;

assert.deepEqual(summarizeSelections([], []), { totalResponses: 0, options: [] });
assert.deepEqual(summarizeSelections([], ['unused']), {
  totalResponses: 0,
  options: [{ option: 'unused', count: 0, respondents: [] }]
});

const allowed = Object.freeze(['beta', 'alpha', 'zero']);
const responses = Object.freeze([
  Object.freeze({ respondent: 'R1', choices: Object.freeze(['beta', 'beta', 'alpha', 'unknown']) }),
  Object.freeze({ respondent: 'R2', choices: Object.freeze(['alpha']) }),
  Object.freeze({ respondent: 'R1', choices: Object.freeze(['beta']) }),
  Object.freeze({ respondent: 'R3', choices: Object.freeze([]) })
]);
const result = summarizeSelections(responses, allowed);
assert.deepEqual(result, {
  totalResponses: 4,
  options: [
    { option: 'alpha', count: 2, respondents: ['R1', 'R2'] },
    { option: 'beta', count: 2, respondents: ['R1', 'R1'] },
    { option: 'zero', count: 0, respondents: [] }
  ]
});
assert.notStrictEqual(result.options[0], result.options[1]);
assert.notStrictEqual(result.options[0].respondents, result.options[1].respondents);
assert.notStrictEqual(result.options, allowed);

for (const bad of [null, {}, 'x']) {
  assert.throws(() => summarizeSelections([], bad), TypeError);
  assert.throws(() => summarizeSelections(bad, []), TypeError);
}
assert.throws(() => summarizeSelections([], ['a', 'a']), TypeError);
assert.throws(() => summarizeSelections([], ['', 'a']), TypeError);
assert.throws(() => summarizeSelections([], ['a', 2]), TypeError);
for (const response of [
  null,
  {},
  { respondent: '', choices: [] },
  { respondent: 'R', choices: 'a' },
  { respondent: 'R', choices: ['a', 2] }
]) {
  assert.throws(() => summarizeSelections([response], ['a']), TypeError);
}

